INSERT INTO `upa_core_module_intls` (`createdAt`, `updatedAt`, `id`, `locale`, `slug`, `titleForce`, `title`, `subTitle`, `subTitlePosition`, `introduction`, `body`, `targetLink`, `targetLabel`, `targetStyle`, `newTab`, `externalLink`, `active`, `placeholder`, `author`, `authorType`, `help`, `error`, `pictogram`, `video`, `associatedWords`, `createdBy_id`, `updatedBy_id`, `targetPage_id`, `website_id`, `module_id`) VALUES
('2026-01-28 11:31:05', NULL, 1, 'fr', NULL, NULL, 'Pages', '', 'bottom', '', 'Espace permettant de visualiser toutes les pages existantes sur votre site internet. Possibilité d\'édition de vos pages grâce à un système de lignes, de colonnes et de blocs.', NULL, NULL, NULL, 0, 0, 1, 'Pages', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
('2026-01-28 11:31:06', NULL, 3, 'fr', NULL, NULL, 'Informations', '', 'bottom', '', 'Espace permettant de remplir les informations vous concernant (adresse, e-mail, téléphone, …).', NULL, NULL, NULL, 0, 0, 1, 'Informations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 3),
('2026-01-28 11:31:06', NULL, 4, 'fr', NULL, NULL, 'Formulaires', '', 'bottom', '', 'Module permettant de créer un ou plusieurs formulaires. Chaque formulaire sera éditable sous forme de colonnes, de lignes et de blocs afin de composer un formulaire selon ses besoins. Possibilité de choisir le réceptionneur du message ainsi que l\'envoyeur.', NULL, NULL, NULL, 0, 0, 1, 'Formulaires', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 4),
('2026-01-28 11:31:06', NULL, 5, 'fr', NULL, NULL, 'Calendrier de formulaire', '', 'bottom', '', 'Module permettant de créer un ou plusieurs calendriers liés à un formulaire. Chaque calendrier permet à l\'utilisateur de choisir un créneau pour un rendez-vous, une réservation, … en remplissant des informations dans le formulaire.', NULL, NULL, NULL, 0, 0, 1, 'Calendrier de formulaire', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 5),
('2026-01-28 11:31:06', NULL, 6, 'fr', NULL, NULL, 'Formulaires à étapes', '', 'bottom', '', 'Module permettant de créer un ou plusieurs formulaires. Chaque formulaire sera composé de plusieurs étapes, dans lesquelles se trouveront des formulaires différents (ex : étape identité, étape demande …)', NULL, NULL, NULL, 0, 0, 1, 'Formulaires à étapes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 6),
('2026-01-28 11:31:06', NULL, 7, 'fr', NULL, NULL, 'Galeries', '', 'bottom', '', 'Module permettant de créer une ou plusieurs galeries photos, dans lesquelles se trouvent une ou plusieurs images.', NULL, NULL, NULL, 0, 0, 1, 'Galeries', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 7),
('2026-01-28 11:31:06', NULL, 8, 'fr', NULL, NULL, 'Médias', '', 'bottom', '', '', NULL, NULL, NULL, 0, 0, 1, 'Médias', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 8),
('2026-01-28 11:31:06', NULL, 9, 'fr', NULL, NULL, 'Actualités', '', 'bottom', '', 'Module permettant de créer plusieurs actualités, toutes catégorisables. Chaque actualité pourra être composée d\'un titre, d\'une introduction, d\'une description, d\'une image mise en avant, d\'images secondaires, d\'une vidéo et d\'un lien', NULL, NULL, NULL, 0, 0, 1, 'Actualités', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 9),
('2026-01-28 11:31:06', NULL, 10, 'fr', NULL, NULL, 'Navigations', '', 'bottom', '', 'Espace permettant de gérer les divers menus se trouvant sur votre site internet.', NULL, NULL, NULL, 0, 0, 1, 'Navigations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 10),
('2026-01-28 11:31:06', NULL, 11, 'fr', NULL, NULL, 'Newsletters', '', 'bottom', '', 'Module permettant d\'agréger les emails de toutes les personnes ayant rempli le champs newsletter dans votre site. Possibilité d\'exporter ces contacts en format CSV, ou de connecter ce champs a votre compte Mailchimp.', NULL, NULL, NULL, 0, 0, 1, 'Newsletters', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 11),
('2026-01-28 11:31:06', NULL, 12, 'fr', NULL, NULL, 'Tableaux', '', 'bottom', '', '', NULL, NULL, NULL, 0, 0, 1, 'Tableaux', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 12),
('2026-01-28 11:31:06', NULL, 13, 'fr', NULL, NULL, NULL, NULL, 'bottom', NULL, NULL, NULL, NULL, NULL, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 13),
('2026-01-28 11:31:07', NULL, 14, 'fr', NULL, NULL, 'Plan de site', '', 'bottom', '', 'Module permettant d\'afficher les pages se trouvant sur votre site et leur arborescence.', NULL, NULL, NULL, 0, 0, 1, 'Plan de site', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 14),
('2026-01-28 11:31:07', NULL, 15, 'fr', NULL, NULL, 'Cartes', '', 'bottom', '', 'Module permettant de créer une ou plusieurs cartes, dans lesquelles se trouvent un ou plusieurs points. Ces points seront définis par une latitude et une longitude, et pourront être agrémentés d\'un nom, d\'une description, d\'une image, d\'une catégorie, d\'un pictogramme (défini en amont) et de liens.', NULL, NULL, NULL, 0, 0, 1, 'Cartes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 15),
('2026-01-28 11:31:07', NULL, 16, 'fr', NULL, NULL, 'Groupes d\'onglets', '', 'bottom', '', 'Bloc permettant d\'afficher plusieurs titres brefs côte à côté. Au clic sur un titre, cela affiche toute la description de ce dernier sous format texte.', NULL, NULL, NULL, 0, 0, 1, 'Groupes d\'onglets', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 16),
('2026-01-28 11:31:07', NULL, 17, 'fr', NULL, NULL, 'Moteurs de recherche', '', 'bottom', '', 'Module permettant d\'ajouter un moteur de recherche à votre site internet.', NULL, NULL, NULL, 0, 0, 1, 'Moteurs de recherche', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 17),
